-- Audit du 03/11 : performances (avertissements Supabase). Politiques identiques, auth.uid() évalué une fois par requête,
-- et index sur les clés étrangères utilisées dans les filtres et suppressions.
drop policy if exists ai_topups_read on public.ai_topups;
create policy ai_topups_read on public.ai_topups for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists ai_usage_read on public.ai_usage;
create policy ai_usage_read on public.ai_usage for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists company_scan_read on public.company_scan;
create policy company_scan_read on public.company_scan for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists competitor_ads_read on public.competitor_ads;
create policy competitor_ads_read on public.competitor_ads for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists competitor_emails_read on public.competitor_emails;
create policy competitor_emails_read on public.competitor_emails for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists public_contracts_read on public.public_contracts;
create policy public_contracts_read on public.public_contracts for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists tech_seen_read on public.tech_seen;
create policy tech_seen_read on public.tech_seen for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists trial_signups_read on public.trial_signups;
create policy trial_signups_read on public.trial_signups for select using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists radar_partners_rw on public.radar_partners;
create policy radar_partners_rw on public.radar_partners for all using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid()))) with check (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists radar_watch_rw on public.radar_watch;
create policy radar_watch_rw on public.radar_watch for all using (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid()))) with check (workspace_id in (select m.workspace_id from public.members m where m.user_id = (select auth.uid())));
drop policy if exists company_names_read on public.company_names;
create policy company_names_read on public.company_names for select using ((select auth.role()) = 'authenticated');
create index if not exists calls_created_by_fk on public.calls (created_by);
create index if not exists calls_prospect_id_fk on public.calls (prospect_id);
create index if not exists company_scan_prospect_id_fk on public.company_scan (prospect_id);
create index if not exists company_scan_watch_id_fk on public.company_scan (watch_id);
create index if not exists competitor_emails_competitor_id_fk on public.competitor_emails (competitor_id);
create index if not exists competitors_workspace_id_fk on public.competitors (workspace_id);
create index if not exists feedback_user_id_fk on public.feedback (user_id);
create index if not exists feedback_workspace_id_fk on public.feedback (workspace_id);
create index if not exists invites_created_by_fk on public.invites (created_by);
create index if not exists invites_used_by_fk on public.invites (used_by);
create index if not exists invites_workspace_id_fk on public.invites (workspace_id);
create index if not exists meetings_prospect_id_fk on public.meetings (prospect_id);
